return function(build,ui,frame)
	local raw="Rarity: NORMAL\nIron Hat\nItem Level: 86";local sim=require("Modules.CraftingSimulator")
	local state=copyTable(sim.model(raw).initial);state.rarity="RARE";state.affixes={{id="IncreasedLife2",range=0.5},{id="FireResist2",range=0.5}}
	require("Classes.CraftingSimulatorControl").Open(build,{id="rog-ui",title="Rog offer",slot="Helmet",startingItem=raw,goals={},steps={},run=require("Modules.CraftingInventory").run(state)})
	ui:click("settings");ui:text("paletteSearch","Rog:");ui:click("paletteUse");assert(not main.popups[1].controls.apply:IsEnabled(),"Unconfigured Rog offer could be applied")
	ui:click("tab_settings");ui:click("configure");frame("crafting-rog-offer")
	ui:choose("operation","socket_links","val");ui:choose("socketRolls",30,"val");assert(main.popups[1].controls.socketHint:IsShown() and not main.popups[1].controls.side:IsShown(),"Socket offer details are missing");frame("crafting-rog-socket-offer")
	ui:choose("operation","remove_lowest_two","val");assert(not main.popups[1].controls.side:IsShown() and main.popups[1].controls.removeHint:IsShown(),"Removal offer did not explain its selection assumption");frame("crafting-rog-removal")
	ui:click("keep");ui:click("exact")
	local jobs=require("Modules.CraftingTasks");for _=1,1000 do if not jobs.job then break end;jobs.tick(build) end
	local odds=build.craftingAnalyses["rog-ui"].results.odds.result
	assert(not jobs.job and not odds.sampled and odds.successChance==100,"Rog removal odds were not enumerated");frame("crafting-rog-odds")
	ui:click("tab_settings");ui:click("configure")
	ui:choose("operation","upgrade","val");ui:choose("upgradeCount",2,"val");assert(main.popups[1].controls.upgradeHint:IsShown(),"Upgrade explanation missing");frame("crafting-rog-upgrade");ui:click("keep");ui:click("tab_craft");assert(main.popups[1].controls.apply:IsEnabled(),"Tier upgrade could not be applied");ui:click("tab_settings");ui:click("configure");assert(main.popups[1].controls.upgradeCount:GetSelValueByKey("val")==2,"Upgrade count was not retained")
	ui:choose("operation","fill","val");assert(main.popups[1].controls.fillHint:IsShown() and not main.popups[1].controls.side:IsShown(),"Fill offer did not explain its estimated rolls");frame("crafting-rog-fill")
	ui:click("keep");ui:click("tab_craft");assert(main.popups[1].controls.apply:IsEnabled(),"Rog fill offer could not be applied");ui:click("tab_settings");ui:click("configure");assert(main.popups[1].controls.operation:GetSelValueByKey("val")=="fill","Rog fill selection was not retained")
	ui:choose("operation","add","val");ui:choose("side","Suffix","val");ui:choose("attempts",3,"val");ui:text("grand","12");ui:click("keep")
	ui:click("tab_craft");assert(main.popups[1].controls.apply:IsEnabled(),"Configured Rog offer could not be applied");ui:click("item");frame("crafting-rog-result")
	ui:click("keepWorking");local saved;for _,project in ipairs(build.savers.CraftingProjects.projects) do if project.id=="rog-ui" then saved=project end end
	assert(saved and saved.run.configured.rog_reroll.artifactCost.grand==12 and saved.run.configured.rog_reroll.rogOperation=="add","Rog offer was not saved");ui:click("close")
	local full=copyTable(state);full.rarity="MAGIC"
	require("Classes.CraftingSimulatorControl").Open(build,{id="rog-full-ui",title="Full magic item",slot="Helmet",startingItem=raw,goals={},steps={},run=require("Modules.CraftingInventory").run(full)})
	ui:click("settings");ui:text("paletteSearch","Rog:");ui:click("paletteUse");ui:click("tab_settings");ui:click("configure")
	ui:choose("operation","add","val");ui:click("keep");ui:click("tab_craft")
	assert(not main.popups[1].controls.apply:IsEnabled() and main.popups[1].controls.apply.tooltipText():find("No open prefix",1,true),"Full side did not explain why the offer is unavailable")
	frame("crafting-rog-full-slot","apply");ui:click("close")
	local recipe;require("Classes.CraftingRecipeControl").Open({steps={{method="alchemy"}},targets={},requirements={minAffixes=6}},{method="alchemy"},function(value) recipe=value end,sim.model(raw))
	ui:click("addCurrency");ui:text("search","Rog: observed offer");ui:click("choose");ui:choose("operation","fill","val");ui:text("grand","7");frame("crafting-recipe-rog-fill");ui:click("keep")
	ui:text("attempts","4");ui:choose("condition","Until final targets and properties match");ui:choose("failure","stop","val");ui:click("editRog")
	assert(main.popups[1].controls.operation:GetSelValueByKey("val")=="fill" and main.popups[1].controls.grand.buf=="7","Edit Rog did not load the saved offer")
	ui:choose("operation","add","val");ui:choose("side","Suffix","val");ui:choose("attempts",3,"val");ui:text("grand","12");frame("crafting-recipe-rog-edit");ui:click("keep");ui:click("keep")
	local step=recipe.steps[2];assert(step.rogOperation=="add" and step.rogSide=="Suffix" and step.rogAttempts==3 and step.artifactCost.grand==12,"Edited Rog offer or price was lost")
	assert(step.maxAttempts==4 and step.untilRequirements.minAffixes==6 and step.onFailureAction=="stop","Editing Rog changed the step's routing or attempts")
	local updated;require("Classes.CraftingRecipeControl").Open(recipe,{method="alchemy"},function(value) updated=value end,sim.model(raw))
	ui:choose("step",2,"val");ui:click("editRog");ui:choose("operation","upgrade","val");ui:choose("upgradeCount",2,"val");ui:click("keep");ui:click("keep")
	assert(updated.steps[2].count==2 and updated.steps[2].rogOperation=="upgrade","Recipe upgrade count was lost")
	local again;require("Classes.CraftingRecipeControl").Open(updated,{method="alchemy"},function(value) again=value end,sim.model(raw))
	ui:choose("step",2,"val");ui:click("editRog");assert(main.popups[1].controls.upgradeCount:GetSelValueByKey("val")==2,"Recipe upgrade count was not loaded");ui:choose("operation","set_quality","val");assert(main.popups[1].controls.qualityHint:IsShown(),"Rog quality explanation is missing");frame("crafting-recipe-rog-quality");ui:click("keep");ui:click("keep")
	step=again.steps[2];assert(step.count==nil and step.rogOperation=="set_quality" and step.rogSide==nil and step.rogAttempts==nil and step.artifactCost.grand==12,"Rog quality edit retained obsolete fields or lost its price")
	assert(step.maxAttempts==4 and step.untilRequirements.minAffixes==6 and step.onFailureAction=="stop","Rog quality edit changed the step's routes")
end
